/*
 * A178477  Permutations of 1234567: Numbers having each of the decimal digits
 *          1,...,7 exactly once, and no other digit.
 * https://oeis.org/A178477
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, full, easy, base
 * Formula:   not stated
 * Range:     u8 none, u16 none, u32 n <= 5040, u64 n <= 5040, u128 n <= 5040,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * Formula: a(n) is the n-th lexicographic permutation of the digits 1–7.
 * The permutation is generated by converting n-1 to factorial number system
 * (factoradic) and selecting digits in order.
 */
seq_t a(idx_t n)
{
    /* 0-based index of the desired permutation */
    idx_t idx = n - 1;

    /* If n exceeds the number of permutations (7! = 5040) wrap around
     * to avoid out of bounds access. This extension is harmless
     * because a(n) is undefined for n > 5040 in the OEIS entry. */
    if (idx >= 5040)
        idx %= 5040;

    /* Precompute factorials 0! … 7! as seq_t */
    seq_t fac[8];
    fac[0] = 1;
    for (int i = 1; i <= 7; ++i)
        fac[i] = fac[i - 1] * (seq_t)i;

    /* Available digits, initially 1…7 */
    int digits[7] = {1, 2, 3, 4, 5, 6, 7};

    seq_t result = 0;
    idx_t k = idx;

    /* Construct the permutation digit by digit */
    for (int i = 7; i >= 1; --i) {
        seq_t f = fac[i - 1];
        idx_t pos = k / (idx_t)f;
        k %= (idx_t)f;

        int d = digits[(int)pos];

        /* Append the chosen digit to the number */
        result = result * 10 + (seq_t)d;

        /* Remove the used digit from the list */
        for (int j = (int)pos; j < 6; ++j)
            digits[j] = digits[j + 1];
    }

    return result;
}
